class Solution {
public:
    void moveZeroes(vector<int>& nums) {
        int n = nums.size();
        // finding '0s'
        int j =-1;
        for (int i=0; i<n; i++){
            if(nums[i]==0){ 
                j=i;
                break;
            }
        }

        // replacing non zeroes with zeroes
        for (int i=j+1; i<n; i++){
            if (nums[i]!= 0){
                int temp = nums[i];
                nums[i] = nums[j];
                nums[j] = temp;
                j++;
            }
        }

    }
};
